package main

import (
	"database/sql"
	"fmt"
	"sync"
	"time"
)

const (
	StMatching  = "MATCHING"
	StEnroute   = "ENROUTE"
	StPickup    = "PICKUP"
	StCarrying  = "CARRYING"
	StArrived   = "ARRIVED"
	StCompleted = "COMPLETED"

	initialFare     = 500
	farePerDistance = 100
)

type Coupon struct {
	Code      string
	Discount  int
	CreatedAt time.Time
	UsedBy    string
}

type StatusEntry struct {
	ID     string
	Status string
	At     time.Time
}

type Ride struct {
	ID         string
	User       *User
	Chair      *Chair
	PickupLat  int
	PickupLon  int
	DestLat    int
	DestLon    int
	Evaluation int
	CreatedAt  time.Time
	UpdatedAt  time.Time
	Statuses   []StatusEntry
	Status     string
	Fare       int
}

type evt struct {
	ride   *Ride
	status string
}

// Notifier holds undelivered events for one recipient (user or chair).
type Notifier struct {
	q   []evt
	sub chan struct{}
}

func (n *Notifier) push(e evt) {
	n.q = append(n.q, e)
	n.wake()
}

