package main

import (
	"database/sql"
	crand "crypto/rand"
	"encoding/json"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/exec"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"github.com/go-sql-driver/mysql"
)

var db *sql.DB

func main() {
	host := envOr("ISUCON_DB_HOST", "127.0.0.1")
	port := envOr("ISUCON_DB_PORT", "3306")
	if _, err := strconv.Atoi(port); err != nil {
		panic(fmt.Sprintf("bad ISUCON_DB_PORT: %v", err))
	}
	cfg := mysql.NewConfig()
	cfg.User = envOr("ISUCON_DB_USER", "isucon")
	cfg.Passwd = envOr("ISUCON_DB_PASSWORD", "isucon")
	cfg.Addr = net.JoinHostPort(host, port)
	cfg.Net = "tcp"
	cfg.DBName = envOr("ISUCON_DB_NAME", "isuride")
	cfg.ParseTime = true
	cfg.InterpolateParams = true
	cfg.Loc = time.UTC

	var err error
	db, err = sql.Open("mysql", cfg.FormatDSN())
	if err != nil {
		panic(err)
	}
	db.SetMaxOpenConns(16)
	db.SetMaxIdleConns(16)
	db.SetConnMaxLifetime(0)

	// wait for DB at boot
	for i := 0; ; i++ {
		if err = db.Ping(); err == nil {
			break
		}
		if i > 120 {
			panic(err)
		}
		slog.Warn("waiting for db", "err", err)
		time.Sleep(time.Second)
	}

	mu.Lock()
	for i := 0; ; i++ {
		if err = loadAll(); err == nil {
			break
		}
		if i > 30 {
			panic(err)
		}
		slog.Warn("load failed, retrying", "err", err)
		time.Sleep(time.Second)
	}
	mu.Unlock()

	startWriter()
	startMatcher()
	startPayWorkers()

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/initialize", postInitialize)

	mux.HandleFunc("POST /api/app/users", appPostUsers)
	mux.HandleFunc("POST /api/app/payment-methods", appPostPaymentMethods)
	mux.HandleFunc("GET /api/app/rides", appGetRides)
	mux.HandleFunc("POST /api/app/rides", appPostRides)
	mux.HandleFunc("POST /api/app/rides/estimated-fare", appPostRidesEstimatedFare)
	mux.HandleFunc("POST /api/app/rides/{ride_id}/evaluation", appPostRideEvaluation)
	mux.HandleFunc("GET /api/app/notification", appGetNotification)
	mux.HandleFunc("GET /api/app/nearby-chairs", appGetNearbyChairs)

	mux.HandleFunc("POST /api/owner/owners", ownerPostOwners)
	mux.HandleFunc("GET /api/owner/sales", ownerGetSales)
	mux.HandleFunc("GET /api/owner/chairs", ownerGetChairs)

	mux.HandleFunc("POST /api/chair/chairs", chairPostChairs)
	mux.HandleFunc("POST /api/chair/activity", chairPostActivity)
	mux.HandleFunc("POST /api/chair/coordinate", chairPostCoordinate)
	mux.HandleFunc("GET /api/chair/notification", chairGetNotification)
	mux.HandleFunc("POST /api/chair/rides/{ride_id}/status", chairPostRideStatus)

	mux.HandleFunc("GET /api/internal/matching", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNoContent)
	})

	srv := &http.Server{Addr: "127.0.0.1:8080", Handler: mux}

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGTERM, syscall.SIGINT, syscall.SIGQUIT)
	go func() {
		<-sigc
		flushWrites()
		os.Exit(0)
	}()

	slog.Info("Listening on :8080")
	if err := srv.ListenAndServe(); err != nil {
		slog.Error("listen", "err", err)
		os.Exit(1)
	}
}

func envOr(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

type postInitializeRequest struct {
	PaymentServer string `json:"payment_server"`
}

type postInitializeResponse struct {
	Language string `json:"language"`
}

func postInitialize(w http.ResponseWriter, r *http.Request) {
	req := &postInitializeRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}

	mu.Lock()
	defer mu.Unlock()
	flushMu.Lock()
	defer flushMu.Unlock()
	discardPending()
	drainPayments()

	if out, err := exec.Command("../sql/init.sh").CombinedOutput(); err != nil {
		writeError(w, http.StatusInternalServerError, fmt.Errorf("failed to initialize: %s: %w", string(out), err))
		return
	}
	if _, err := db.Exec("UPDATE settings SET value = ? WHERE name = 'payment_gateway_url'", req.PaymentServer); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}
	if err := loadAll(); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}
	paymentURL = req.PaymentServer

	writeJSON(w, http.StatusOK, postInitializeResponse{Language: "go"})
}

type Coordinate struct {
	Latitude  int `json:"latitude"`
	Longitude int `json:"longitude"`
}

func bindJSON(r *http.Request, v interface{}) error {
	return json.NewDecoder(r.Body).Decode(v)
}

func writeJSON(w http.ResponseWriter, statusCode int, v interface{}) {
	buf, err := json.Marshal(v)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json;charset=utf-8")
	w.WriteHeader(statusCode)
	w.Write(buf)
}

func writeError(w http.ResponseWriter, statusCode int, err error) {
	w.Header().Set("Content-Type", "application/json;charset=utf-8")
	w.WriteHeader(statusCode)
	buf, _ := json.Marshal(map[string]string{"message": err.Error()})
	w.Write(buf)
	if statusCode >= 500 {
		slog.Error("error response", "status", statusCode, "err", err)
	}
}

func secureRandomStr(b int) string {
	k := make([]byte, b)
	if _, err := crand.Read(k); err != nil {
		panic(err)
	}
	return fmt.Sprintf("%x", k)
}

func nowUS() time.Time {
	return time.Now().UTC().Truncate(time.Microsecond)
}

func cookieVal(r *http.Request, name string) string {
	c, err := r.Cookie(name)
	if err != nil {
		return ""
	}
	return c.Value
}

