	var coupon *Coupon
	if len(user.Rides) == 0 {
		for _, cp := range user.Coupons {
			if cp.Code == "CP_NEW2024" && cp.UsedBy == "" {
				coupon = cp
				break
			}
		}
	}
	if coupon == nil {
		for _, cp := range user.Coupons {
			if cp.UsedBy == "" {
				coupon = cp
				break
			}
		}
	}
	discount := 0
	if coupon != nil {
		coupon.UsedBy = ride.ID
		discount = coupon.Discount
		enqueue("UPDATE coupons SET used_by = ? WHERE user_id = ? AND code = ?", ride.ID, user.ID, coupon.Code)
	}
	ride.Fare = discountedFare(ride.PickupLat, ride.PickupLon, ride.DestLat, ride.DestLon, discount)

