type appPostRideEvaluationRequest struct {
	Evaluation int `json:"evaluation"`
}

type appPostRideEvaluationResponse struct {
	CompletedAt int64 `json:"completed_at"`
}

func appPostRideEvaluation(w http.ResponseWriter, r *http.Request) {
	rideID := r.PathValue("ride_id")
	req := &appPostRideEvaluationRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Evaluation < 1 || req.Evaluation > 5 {
		writeError(w, http.StatusBadRequest, errors.New("evaluation must be between 1 and 5"))
		return
	}

	status, completedAt, job, err := func() (int, int64, *payJob, error) {
		mu.Lock()
		defer mu.Unlock()
		ride := ridesByID[rideID]
		if ride == nil {
			return http.StatusNotFound, 0, nil, errors.New("ride not found")
		}
		if ride.Status != StArrived {
			return http.StatusBadRequest, 0, nil, errors.New("not arrived yet")
		}
		if ride.User.PayToken == "" {
			return http.StatusBadRequest, 0, nil, errors.New("payment token not registered")
		}
		now := nowUS()
		ride.Evaluation = req.Evaluation
		ride.UpdatedAt = now
		enqueue("UPDATE rides SET evaluation = ?, updated_at = ? WHERE id = ?", ride.Evaluation, now, ride.ID)
		addStatusLocked(ride, StCompleted, now)
		if c := ride.Chair; c != nil {
			c.StatCount++
			c.StatEvalSum += ride.Evaluation
			c.Completed = append(c.Completed, ride)
		}
		// mark all statuses as sent (persisted lazily)
		ids := make([]any, 0, len(ride.Statuses))
		ph := ""
		for i, s := range ride.Statuses {
			ids = append(ids, s.ID)
			if i > 0 {
				ph += ","
			}
			ph += "?"
		}
		enqueue("UPDATE ride_statuses SET app_sent_at = created_at, chair_sent_at = created_at WHERE id IN ("+ph+")", ids...)
		job = &payJob{rideID: ride.ID, url: paymentURL, token: ride.User.PayToken, amount: ride.Fare, gen: loadGen}
		return http.StatusOK, ride.UpdatedAt.UnixMilli(), job, nil
	}()
	if err != nil {
		writeError(w, status, err)
		return
	}
	submitPayment(job)
	writeJSON(w, http.StatusOK, &appPostRideEvaluationResponse{CompletedAt: completedAt})
}

func appGetNearbyChairs(w http.ResponseWriter, r *http.Request) {
	latStr := r.URL.Query().Get("latitude")
	lonStr := r.URL.Query().Get("longitude")
	distanceStr := r.URL.Query().Get("distance")
	if latStr == "" || lonStr == "" {
		writeError(w, http.StatusBadRequest, errors.New("latitude or longitude is empty"))
		return
	}
	lat, err := strconv.Atoi(latStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("latitude is invalid"))
		return
	}
	lon, err := strconv.Atoi(lonStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("longitude is invalid"))
		return
	}
	distance := 50
	if distanceStr != "" {
		distance, err = strconv.Atoi(distanceStr)
		if err != nil {
			writeError(w, http.StatusBadRequest, errors.New("distance is invalid"))
			return
		}
	}
	if authUser(w, r) == nil {
		return
	}

	type chairOut struct {
		ID                string     `json:"id"`
		Name              string     `json:"name"`
		Model             string     `json:"model"`
		CurrentCoordinate Coordinate `json:"current_coordinate"`
	}
	type resp struct {
		Chairs      []chairOut `json:"chairs"`
		RetrievedAt int64      `json:"retrieved_at"`
	}
	out := resp{Chairs: []chairOut{}}
	mu.RLock()
	for _, c := range allChairs {
		if !c.IsActive || !c.HasLoc {
			continue
		}
		if c.Cur != nil && c.Cur.Status != StCompleted {
			continue
		}
		if dist(lat, lon, c.Lat, c.Lon) <= distance {
			out.Chairs = append(out.Chairs, chairOut{ID: c.ID, Name: c.Name, Model: c.Model, CurrentCoordinate: Coordinate{c.Lat, c.Lon}})
		}
	}
	mu.RUnlock()
	out.RetrievedAt = time.Now().UnixMilli()
	writeJSON(w, http.StatusOK, &out)
}

