type appPostUsersRequest struct {
	Username       string  `json:"username"`
	FirstName      string  `json:"firstname"`
	LastName       string  `json:"lastname"`
	DateOfBirth    string  `json:"date_of_birth"`
	InvitationCode *string `json:"invitation_code"`
}

type appPostUsersResponse struct {
	ID             string `json:"id"`
	InvitationCode string `json:"invitation_code"`
}

func appPostUsers(w http.ResponseWriter, r *http.Request) {
	req := &appPostUsersRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Username == "" || req.FirstName == "" || req.LastName == "" || req.DateOfBirth == "" {
		writeError(w, http.StatusBadRequest, errors.New("required fields(username, firstname, lastname, date_of_birth) are empty"))
		return
	}

	userID := ulid.Make().String()
	accessToken := secureRandomStr(32)
	invitationCode := secureRandomStr(15)

	status, resp, err := func() (int, *appPostUsersResponse, error) {
		mu.Lock()
		defer mu.Unlock()

		if _, ok := usersByName[req.Username]; ok {
			return http.StatusInternalServerError, nil, errors.New("duplicate username")
		}
		now := nowUS()
		var inviter *User
		invited := req.InvitationCode != nil && *req.InvitationCode != ""
		if invited {
			code := *req.InvitationCode
			if invCount["INV_"+code] >= 3 {
				return http.StatusBadRequest, nil, errors.New("この招待コードは使用できません。")
			}
			inviter = usersByInv[code]
			if inviter == nil {
				return http.StatusBadRequest, nil, errors.New("この招待コードは使用できません。")
			}
		}

		u := &User{
			ID: userID, Username: req.Username, Firstname: req.FirstName, Lastname: req.LastName,
			DOB: req.DateOfBirth, Token: accessToken, InvCode: invitationCode, CreatedAt: now,
		}
		usersByID[u.ID] = u
		usersByToken[u.Token] = u
		usersByName[u.Username] = u
		usersByInv[u.InvCode] = u
		enqueue("INSERT INTO users (id, username, firstname, lastname, date_of_birth, access_token, invitation_code, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
			u.ID, u.Username, u.Firstname, u.Lastname, u.DOB, u.Token, u.InvCode, now, now)

		addCoupon := func(to *User, code string, discount int, at time.Time) {
			cp := &Coupon{Code: code, Discount: discount, CreatedAt: at}
			to.Coupons = append(to.Coupons, cp)
			enqueue("INSERT INTO coupons (user_id, code, discount, created_at) VALUES (?, ?, ?, ?)", to.ID, code, discount, at)
		}
		addCoupon(u, "CP_NEW2024", 3000, now)

		if invited {
			code := *req.InvitationCode
			addCoupon(u, "INV_"+code, 1500, now.Add(time.Microsecond))
			invCount["INV_"+code]++
			ms := now.UnixMilli()
			rwd := "RWD_" + code + "_" + strconv.FormatInt(ms, 10)
			for {
				dup := false
				for _, cp := range inviter.Coupons {
					if cp.Code == rwd {
						dup = true
						break
					}
				}
				if !dup {
					break
				}
				ms++
				rwd = "RWD_" + code + "_" + strconv.FormatInt(ms, 10)
			}
			addCoupon(inviter, rwd, 1000, now.Add(2*time.Microsecond))
		}
		return http.StatusCreated, &appPostUsersResponse{ID: userID, InvitationCode: invitationCode}, nil
	}()
	if err != nil {
		writeError(w, status, err)
		return
	}

	http.SetCookie(w, &http.Cookie{Path: "/", Name: "app_session", Value: accessToken})
	writeJSON(w, http.StatusCreated, resp)
}

