	}
	req := &Coordinate{}
	if err := bindJSON(r, req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	now := nowUS()
	mu.Lock()
	if chair.HasLoc {
		chair.TotalDistance += dist(chair.Lat, chair.Lon, req.Latitude, req.Longitude)
	}
	chair.HasLoc = true
	chair.Lat, chair.Lon, chair.LocAt = req.Latitude, req.Longitude, now
	enqueueLoc(chair.ID, req.Latitude, req.Longitude, now)
	if ride := chair.Cur; ride != nil && ride.Status != StCompleted {
		status := ride.Status
		if req.Latitude == ride.PickupLat && req.Longitude == ride.PickupLon && status == StEnroute {
			addStatusLocked(ride, StPickup, now)
		}
		if req.Latitude == ride.DestLat && req.Longitude == ride.DestLon && status == StCarrying {
			addStatusLocked(ride, StArrived, now)
		}
	}
	mu.Unlock()
