	Status string `json:"status"`
}

func chairPostRideStatus(w http.ResponseWriter, r *http.Request) {
	rideID := r.PathValue("ride_id")
	chair := authChair(w, r)
	if chair == nil {
		return
	}
	req := &postChairRidesRideIDStatusRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	mu.Lock()
	ride := ridesByID[rideID]
	if ride == nil {
		mu.Unlock()
		writeError(w, http.StatusNotFound, errors.New("ride not found"))
		return
	}
	if ride.Chair == nil || ride.Chair.ID != chair.ID {
		mu.Unlock()
		writeError(w, http.StatusBadRequest, errors.New("not assigned to this ride"))
		return
	}
	now := nowUS()
	switch req.Status {
	case StEnroute:
		if ride.Status == StMatching {
			addStatusLocked(ride, StEnroute, now)
		}
	case StCarrying:
		if ride.Status != StPickup {
			mu.Unlock()
			writeError(w, http.StatusBadRequest, errors.New("chair has not arrived yet"))
			return
		}
		addStatusLocked(ride, StCarrying, now)
	default:
		mu.Unlock()
		writeError(w, http.StatusBadRequest, errors.New("invalid status"))
		return
	}
	mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

// addStatusLocked appends a status to the ride and queues notifications. mu must be held.
func addStatusLocked(ride *Ride, status string, at time.Time) {
	id := ulid.Make().String()
	ride.Statuses = append(ride.Statuses, StatusEntry{ID: id, Status: status, At: at})
	ride.Status = status
	enqueue("INSERT INTO ride_statuses (id, ride_id, status, created_at) VALUES (?, ?, ?, ?)", id, ride.ID, status, at)
	ride.User.N.push(evt{ride, status})
	if ride.Chair != nil {
		ride.Chair.N.push(evt{ride, status})
	}
}

