var useSSE = os.Getenv("NOTIFY_SSE") != "0"

type userNotifChairStats struct {
	TotalRidesCount    int     `json:"total_rides_count"`
	TotalEvaluationAvg float64 `json:"total_evaluation_avg"`
}

type userNotifChair struct {
	ID    string              `json:"id"`
	Name  string              `json:"name"`
	Model string              `json:"model"`
	Stats userNotifChairStats `json:"stats"`
