package main

import (
	"os"
	"strconv"
	"time"
)

var matchCh = make(chan struct{}, 1)

var matchBeta = func() float64 {
	if v := os.Getenv("MATCH_BETA"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			return f
		}
	}
	return 1.0
}()

func triggerMatch() {
	select {
	case matchCh <- struct{}{}:
	default:
	}
}

func startMatcher() {
	go func() {
		t := time.NewTicker(100 * time.Millisecond)
		for {
			select {
			case <-matchCh:
			case <-t.C:
			}
			mu.Lock()
			runMatchingLocked()
			mu.Unlock()
		}
	}()
}

type cand struct {
	ri, ci int
	cost   float64
}

func runMatchingLocked() {
	if len(waiting) == 0 {
		return
	}
	var free []*Chair
	for _, c := range allChairs {
		if c.IsActive && !c.Busy && c.HasLoc {
			free = append(free, c)
		}
	}
	if len(free) == 0 {
		return
	}
	rides := waiting
	if max := 40000 / len(free); len(rides) > max {
		rides = rides[:max]
	}
	now := time.Now()
	cands := make([]cand, 0, len(rides)*len(free))
	for ri, r := range rides {
		L := dist(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon)
		age := now.Sub(r.CreatedAt).Seconds()
		for ci, c := range free {
			d := dist(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
			cost := float64(d+L)/float64(c.Speed) - matchBeta*age
			cands = append(cands, cand{ri, ci, cost})
		}
	}
	sortSlice(cands, func(a, b cand) bool { return a.cost < b.cost })
	usedR := make([]bool, len(rides))
	usedC := make([]bool, len(free))
	matched := 0
	at := nowUS()
	for _, cd := range cands {
		if usedR[cd.ri] || usedC[cd.ci] {
			continue
		}
		usedR[cd.ri] = true
		usedC[cd.ci] = true
		matched++
		r, c := rides[cd.ri], free[cd.ci]
		r.Chair = c
		r.UpdatedAt = at
		c.Cur = r
		c.Busy = true
		enqueue("UPDATE rides SET chair_id = ?, updated_at = ? WHERE id = ?", c.ID, at, r.ID)
		c.N.push(evt{r, StMatching})
		if matched == len(rides) || matched == len(free) {
			break
		}
	}
	if matched > 0 {
		nw := waiting[:0:0]
		for _, r := range waiting {
			if r.Chair == nil {
				nw = append(nw, r)
			}
		}
		waiting = nw
	}
}

