package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
)

var useSSE = os.Getenv("NOTIFY_SSE") != "0"

type userNotifChairStats struct {
	TotalRidesCount    int     `json:"total_rides_count"`
	TotalEvaluationAvg float64 `json:"total_evaluation_avg"`
}

type userNotifChair struct {
	ID    string              `json:"id"`
	Name  string              `json:"name"`
	Model string              `json:"model"`
	Stats userNotifChairStats `json:"stats"`
}

type userNotifData struct {
	RideID                string          `json:"ride_id"`
	PickupCoordinate      Coordinate      `json:"pickup_coordinate"`
	DestinationCoordinate Coordinate      `json:"destination_coordinate"`
	Fare                  int             `json:"fare"`
	Status                string          `json:"status"`
	Chair                 *userNotifChair `json:"chair,omitempty"`
	CreatedAt             int64           `json:"created_at"`
	UpdateAt              int64           `json:"updated_at"`
}

type simpleUser struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type chairNotifData struct {
	RideID                string     `json:"ride_id"`
	User                  simpleUser `json:"user"`
	PickupCoordinate      Coordinate `json:"pickup_coordinate"`
	DestinationCoordinate Coordinate `json:"destination_coordinate"`
	Status                string     `json:"status"`
}

func userPayloadLocked(ride *Ride, status string) []byte {
	d := &userNotifData{
		RideID:                ride.ID,
		PickupCoordinate:      Coordinate{ride.PickupLat, ride.PickupLon},
		DestinationCoordinate: Coordinate{ride.DestLat, ride.DestLon},
		Fare:                  ride.Fare,
		Status:                status,
		CreatedAt:             ride.CreatedAt.UnixMilli(),
		UpdateAt:              ride.UpdatedAt.UnixMilli(),
	}
	if c := ride.Chair; c != nil {
		st := userNotifChairStats{TotalRidesCount: c.StatCount}
		if c.StatCount > 0 {
			st.TotalEvaluationAvg = float64(c.StatEvalSum) / float64(c.StatCount)
		}
		d.Chair = &userNotifChair{ID: c.ID, Name: c.Name, Model: c.Model, Stats: st}
	}
	b, _ := json.Marshal(d)
	return b
}

func chairPayloadLocked(ride *Ride, status string) []byte {
	d := &chairNotifData{
		RideID:                ride.ID,
		User:                  simpleUser{ID: ride.User.ID, Name: ride.User.Firstname + " " + ride.User.Lastname},
		PickupCoordinate:      Coordinate{ride.PickupLat, ride.PickupLon},
		DestinationCoordinate: Coordinate{ride.DestLat, ride.DestLon},
		Status:                status,
	}
	b, _ := json.Marshal(d)
	return b
}

type streamer struct {
	n         *Notifier
	build     func(e evt) []byte // mu held
	latest    func() []byte      // mu held; nil when nothing to send
	delivered func(e evt)        // mu (write) held
}

func userStreamer(u *User) *streamer {
	return &streamer{
		n:     &u.N,
		build: func(e evt) []byte { return userPayloadLocked(e.ride, e.status) },
		latest: func() []byte {
			if len(u.Rides) == 0 {
				return nil
			}
			r := u.Rides[len(u.Rides)-1]
			return userPayloadLocked(r, r.Status)
		},
	}
}

func chairStreamer(c *Chair) *streamer {
	return &streamer{
		n:     &c.N,
		build: func(e evt) []byte { return chairPayloadLocked(e.ride, e.status) },
		latest: func() []byte {
			if c.Cur == nil {
				return nil
			}
			return chairPayloadLocked(c.Cur, c.Cur.Status)
		},
		delivered: func(e evt) {
			if e.status == StCompleted && c.Cur == e.ride {
				c.Busy = false
				triggerMatch()
			}
		},
	}
}

func appGetNotification(w http.ResponseWriter, r *http.Request) {
	user := authUser(w, r)
	if user == nil {
		return
	}
	s := userStreamer(user)
	if useSSE {
		serveStream(w, r, s)
	} else {
		servePoll(w, s)
	}
}

func chairGetNotification(w http.ResponseWriter, r *http.Request) {
	chair := authChair(w, r)
	if chair == nil {
		return
	}
	s := chairStreamer(chair)
	if useSSE {
		serveStream(w, r, s)
	} else {
		servePoll(w, s)
	}
}

func servePoll(w http.ResponseWriter, s *streamer) {
	var payload []byte
	mu.Lock()
	if len(s.n.q) > 0 {
		e := s.n.q[0]
		s.n.q = s.n.q[1:]
		payload = s.build(e)
		if s.delivered != nil {
			s.delivered(e)
		}
	} else {
		payload = s.latest()
	}
	mu.Unlock()
	var buf bytes.Buffer
	buf.WriteString(`{"data":`)
	if payload == nil {
		buf.WriteString("null")
	} else {
		buf.Write(payload)
	}
	buf.WriteString(`,"retry_after_ms":30}`)
	w.Header().Set("Content-Type", "application/json;charset=utf-8")
	w.WriteHeader(http.StatusOK)
	w.Write(buf.Bytes())
}

func serveStream(w http.ResponseWriter, r *http.Request, s *streamer) {
	h := w.Header()
	h.Set("Content-Type", "text/event-stream")
	h.Set("Cache-Control", "no-cache")
	h.Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	rc := http.NewResponseController(w)
	rc.Flush()

	mine := make(chan struct{}, 1)
	mu.Lock()
	if s.n.sub != nil {
		close(s.n.sub)
	}
	s.n.sub = mine
	mu.Unlock()
	defer func() {
		mu.Lock()
		if s.n.sub == mine {
			s.n.sub = nil
		}
		mu.Unlock()
	}()

	ctx := r.Context()
	first := true
	var buf bytes.Buffer
	for {
		mu.Lock()
		evs := s.n.q
		s.n.q = nil
		buf.Reset()
		if first && len(evs) == 0 {
			if p := s.latest(); p != nil {
				fmt.Fprintf(&buf, "data: %s\n\n", p)
			}
		}
		first = false
		for _, e := range evs {
			fmt.Fprintf(&buf, "data: %s\n\n", s.build(e))
		}
		mu.Unlock()

		if buf.Len() > 0 {
			_, err := w.Write(buf.Bytes())
			if err == nil {
				err = rc.Flush()
			}
			if err != nil {
				if len(evs) > 0 {
					mu.Lock()
					s.n.q = append(evs, s.n.q...)
					mu.Unlock()
				}
				return
			}
			if s.delivered != nil && len(evs) > 0 {
				mu.Lock()
				for _, e := range evs {
					s.delivered(e)
				}
				mu.Unlock()
			}
		}

		select {
		case _, ok := <-mine:
			if !ok {
				return
			}
		case <-ctx.Done():
			return
		}
	}
}

