package main

import (
	"bytes"
	"errors"
	"log/slog"
	"net/http"
	"strconv"
	"sync/atomic"
	"time"
)

type payJob struct {
	rideID string
	url    string
	token  string
	amount int
	gen    int
}

var (
	payClient = &http.Client{
		Timeout: 5 * time.Second,
		Transport: &http.Transport{
			MaxIdleConns:        512,
			MaxIdleConnsPerHost: 512,
			IdleConnTimeout:     60 * time.Second,
		},
	}
	payCount, payFail, payNanos, payMaxNanos int64
)

func drainPayments() {}

func startPayWorkers() {
	go func() {
		t := time.NewTicker(5 * time.Second)
		for range t.C {
			n := atomic.SwapInt64(&payCount, 0)
			f := atomic.SwapInt64(&payFail, 0)
			ns := atomic.SwapInt64(&payNanos, 0)
			mx := atomic.SwapInt64(&payMaxNanos, 0)
			if n > 0 || f > 0 {
				avg := time.Duration(0)
				if n > 0 {
					avg = time.Duration(ns / n)
				}
				slog.Info("payment stats", "ok", n, "fail", f, "avg", avg, "max", time.Duration(mx))
			}
		}
	}()
}

// doPayment posts the payment synchronously, retrying with an Idempotency-Key.
func doPayment(j *payJob) error {
	body := []byte(`{"amount":` + strconv.Itoa(j.amount) + `}`)
	start := time.Now()
	deadline := start.Add(8 * time.Second)
	for attempt := 0; ; attempt++ {
		req, err := http.NewRequest(http.MethodPost, j.url+"/payments", bytes.NewReader(body))
		if err != nil {
			return err
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Authorization", "Bearer "+j.token)
		req.Header.Set("Idempotency-Key", j.rideID)
		res, err := payClient.Do(req)
		if err == nil {
			res.Body.Close()
			if res.StatusCode == http.StatusNoContent {
				el := int64(time.Since(start))
				atomic.AddInt64(&payCount, 1)
				atomic.AddInt64(&payNanos, el)
				for {
					m := atomic.LoadInt64(&payMaxNanos)
					if el <= m || atomic.CompareAndSwapInt64(&payMaxNanos, m, el) {
						break
					}
				}
				return nil
			}
			slog.Warn("payment non-204", "status", res.StatusCode, "attempt", attempt)
		} else {
			slog.Warn("payment error", "err", err, "attempt", attempt)
		}
		atomic.AddInt64(&payFail, 1)
		if time.Now().After(deadline) {
