cat > stats.go <<'EOF'
package main

import (
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"runtime/pprof"
	"strings"
	"sync/atomic"
	"time"
)

type namedCounter struct {
	name string
	n    int64
	last int64
}

var counters []*namedCounter

func counted(name string, h http.HandlerFunc) http.HandlerFunc {
	c := &namedCounter{name: name}
	counters = append(counters, c)
	return func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt64(&c.n, 1)
		h(w, r)
	}
}

func startStats() {
	go func() {
		t := time.NewTicker(5 * time.Second)
		for range t.C {
			var sb strings.Builder
			total := int64(0)
			for _, c := range counters {
				n := atomic.LoadInt64(&c.n)
				d := n - c.last
				c.last = n
				total += d
				if d > 0 {
					fmt.Fprintf(&sb, " %s=%d", c.name, d)
				}
			}
			if total > 0 {
				mu.RLock()
				nw, nc := len(waiting), len(allChairs)
				mu.RUnlock()
				slog.Info("reqs/5s", "total", total, "waiting", nw, "chairs", nc, "detail", sb.String())
			}
		}
	}()
}

var profiling int32

// maybeProfile captures a CPU profile in the middle of a benchmark run.
func maybeProfile() {
	if os.Getenv("PROFILE") != "1" || !atomic.CompareAndSwapInt32(&profiling, 0, 1) {
		return
	}
	go func() {
		defer atomic.StoreInt32(&profiling, 0)
		time.Sleep(38 * time.Second)
		name := fmt.Sprintf("/tmp/cpu-%d.prof", time.Now().Unix())
		f, err := os.Create(name)
		if err != nil {
			return
		}
		defer f.Close()
		if err := pprof.StartCPUProfile(f); err != nil {
			return
		}
		time.Sleep(12 * time.Second)
		pprof.StopCPUProfile()
		slog.Info("cpu profile written", "file", name)
	}()
}
EOF
