// ---- latency instrumentation (all atomics; reset every 5s window)
type lagStat struct {
	n, sum, max, over50ms int64
}

func (l *lagStat) rec(ns int64) {
	atomic.AddInt64(&l.n, 1)
	atomic.AddInt64(&l.sum, ns)
	if ns > 50e6 {
		atomic.AddInt64(&l.over50ms, 1)
	}
	for {
		m := atomic.LoadInt64(&l.max)
		if ns <= m || atomic.CompareAndSwapInt64(&l.max, m, ns) {
			break
		}
	}
}

func (l *lagStat) snap() string {
	n := atomic.SwapInt64(&l.n, 0)
	sum := atomic.SwapInt64(&l.sum, 0)
	mx := atomic.SwapInt64(&l.max, 0)
	o := atomic.SwapInt64(&l.over50ms, 0)
	if n == 0 {
		return "n=0"
	}
	return fmt.Sprintf("n=%d avg=%.2fms max=%.1fms >50ms=%d", n, float64(sum)/float64(n)/1e6, float64(mx)/1e6, o)
}

var sseLag, lockWait, tickStat lagStat

func recordLag(ns int64)      { sseLag.rec(ns) }
func recordLockWait(ns int64) { lockWait.rec(ns) }
func recordTick(ns int64)     { tickStat.rec(ns) }

var lastNumGC uint32
var lastPause uint64

func startLatencyLog() {
	go func() {
		t := time.NewTicker(5 * time.Second)
		for range t.C {
			var ms runtime.MemStats
			runtime.ReadMemStats(&ms)
			dg := ms.NumGC - lastNumGC
			dp := ms.PauseTotalNs - lastPause
			lastNumGC, lastPause = ms.NumGC, ms.PauseTotalNs
			slog.Info("latency",
